import json,sys,base64,re
def b(s):
    s=s.replace('-','+').replace('_','/'); s+='='*(-len(s)%4)
    return base64.b64decode(s).decode('utf-8','replace')
def walk(p,out):
    if p.get('body',{}).get('data') and p.get('mimeType','text/plain').startswith('text/plain'):
        out.append(b(p['body']['data']))
    for c in p.get('parts',[]) or []: walk(c,out)
def show(m,maxlen):
