    print('---',h.get('Date'),'| From:',h.get('From'),'| To:',h.get('To'),'| Cc:',h.get('Cc'),'| Subj:',h.get('Subject'))
    out=[];walk(m['payload'],out)
    t='\n'.join(out)
    # strip quoted
    lines=[l for l in t.splitlines() if not l.startswith('>')]
    t='\n'.join(lines)
    t=re.split(r'\nOn .{5,80}wrote:',t)[0]
    print(t[:maxlen].strip())
